const raw = $input.first().json.output;
const cleaned = raw.replace(/```json|```/g, '').trim();
const parsed = JSON.parse(cleaned);

return [{ json: { finance_top2: parsed } }]

const d = $input.first().json;

// Get urban temp (Observatory as reference)
const obsTemp = d.temperature.data.find(t => t.place === "Hong Kong Observatory");
const maxTemp = Math.max(...d.temperature.data.map(t => t.value));
const minTemp = Math.min(...d.temperature.data.map(t => t.value));
const hottest = d.temperature.data.find(t => t.value === maxTemp);

return [{
  json: {
    current_conditions: {
      urban_temp: `${obsTemp.value}°C`,
      highest_temp: `${maxTemp}°C at ${hottest.place}`,
      lowest_temp: `${minTemp}°C`,
      humidity: `${d.humidity.data[0].value}%`,
      uv_index: `${d.uvindex.data[0].value} (${d.uvindex.data[0].desc})`,
      rainfall_last_hour: "0mm across all districts",
      warning: d.warningMessage[0] || "None",
      updated_at: d.updateTime
    }
  }
}]

const items = $input.all();

// Find each data piece from the 5 items
const weather = items.find(i => i.json.generalSituation)?.json;
const conditions = items.find(i => i.json.current_conditions)?.json.current_conditions;
const local = items.find(i => i.json.local_top2)?.json.local_top2;
const international = items.find(i => i.json.international_top2)?.json.international_top2;
const finance = items.find(i => i.json.finance_top2)?.json.finance_top2;

return [{
  json: {
    weather: {
      situation: weather.generalSituation,
      forecast: weather.forecastDesc,
      outlook: weather.outlook,
      updated_at: weather.updateTime
    },
    current_conditions: conditions,
    local_top2: local,
    international_top2: international,
    finance_top2: finance,
    generated_at: new Date().toISOString()
  }
}]
